    97  static bool IsSupported(const TgaHeader &head)
    98  {
    99      if (head.image_type != TGA_TYPE_INDEXED &&
   100              head.image_type != TGA_TYPE_RGB &&
   101              head.image_type != TGA_TYPE_GREY &&
   102              head.image_type != TGA_TYPE_RLE_INDEXED &&
   103              head.image_type != TGA_TYPE_RLE_RGB &&
   104              head.image_type != TGA_TYPE_RLE_GREY) {
   105          return false;
   106      }
   107      if (head.image_type == TGA_TYPE_INDEXED ||
   108              head.image_type == TGA_TYPE_RLE_INDEXED) {
   109          if (head.colormap_length > 256 || head.colormap_size != 24 || head.colormap_type != 1) {
   110              return false;
   111          }
   112      }
   113      if (head.image_type == TGA_TYPE_RGB ||
   114              head.image_type == TGA_TYPE_GREY ||
   115              head.image_type == TGA_TYPE_RLE_RGB ||
   116              head.image_type == TGA_TYPE_RLE_GREY) {
   117          if (head.colormap_type != 0) {
   118              return false;
   119          }
   120      }
   121      if (head.width == 0 || head.height == 0) {
   122          return false;
   123      }
   124      if (head.pixel_size != 8 && head.pixel_size != 16 &&
   125              head.pixel_size != 24 && head.pixel_size != 32) {
   126          return false;
   127      }
   128      return true;
   129  }
